"use client"

// Orbit CRM Template — A complete, interactive landing page and revenue
// system application template for an AI-powered CRM startup, inspired by
// Saboor (@uisabor).
//
// The visual thesis marries classical antiquity engravings (a Roman emperor
// addressing a legion with aquila standards and spears, classical philosopher
// busts, ancient trireme galleys cutting through ocean waves, and Roman
// architectural colonnades) with royal cobalt blue (#0522E8) AI SaaS ergonomics
// and high-contrast editorial serif typography.
//
// Interactive features:
// - Top Navigation with interactive mega-menus for Products and Solutions,
//   plus live mobile menu drawer
// - Announcement Sub-bar with live client logo SVGs (ClassPass, Calendly, GitHub,
//   Basecamp, Attentive) and real customer count
// - Hero Stage with editorial serif headline, parallax depth on classical Roman
//   regalia, and interactive Video Walkthrough Modal
// - 6-Card Interactive Bento Grid:
//   1. AI Sales Assistant with prompt suggestion chips, live text entry, and
//      simulated workflow runner
//   2. Contact Intelligence with interactive permissions manager and role editors
//   3. Revenue Retention Forecasting with interactive SME / Enterprise / Startup
//      segment tabs and hover tooltips across Apr-Oct bar charts
//   4. Management Finance hub with active status indicators and location tags
//   5. Integrations ecosystem with live toggle switches for Slack, Shopify, Notion,
//      and Zapier
// - "Why Traditional CRM Slows Teams Down" comparison table featuring the classical
//   philosopher bust backdrop, interactive row highlights, and feature diffs
// - "Built For Modern Revenue Teams" with interactive project progress card (Monday.com
//   Redesign), Roman archway background, AI Deal Insights, and Smart Follow-ups
// - "From Lead to Revenue" 3-step interactive pipeline accordion paired with an
//   ancient trireme galley warship dot-matrix revenue chart
// - "AI CRM For Every Team" complete interactive application dashboard:
//   * Active sidebar navigation with live task counters (Backlog, In Progress,
//     Validation, Done)
//   * Top search bar with [Cmd+K] keyboard listener and Ask AI copilot
//   * 4 live KPI metric cards with weekly growth deltas
//   * Interactive Leads Management panel (Status, Sources, Qualification tabs)
//   * Interactive SVG Revenue Chart with timeframe toggles and crosshair hover
//   * Retention Rate gauge, Top Customer Locations ranking, and Events schedule
// - Customer Case Study (Stripe) featuring the Classical Thinker sculpture and
//   interactive team member task status toggles
// - Monumental Caesar Roman army engraving footer with interactive newsletter
//   validation and sitemap navigation
//
// Requires `gsap` and `gsap/ScrollTrigger`.
import * as React from "react"
import { gsap } from "gsap"
import { ScrollTrigger } from "gsap/ScrollTrigger"

if (typeof window !== "undefined") {
  gsap.registerPlugin(ScrollTrigger)
}

export interface OrbitCrmTemplateProps {
  /** Height of the hero viewport stage; defaults to 100svh. */
  height?: string
  className?: string
  /** Primary classical Roman emperor/general engraving backdrop for hero. */
  heroImage?: string
  /** Classical Caesar legion engraving for the monumental footer. */
  caesarImage?: string
  /** Classical galleon trireme warship for the revenue chart backdrop. */
  shipImage?: string
  /** Classical Greek thinker statue for the Stripe testimonial backdrop. */
  thinkerImage?: string
  /** Classical philosopher bust engraving for the comparison table. */
  tableBustImage?: string
  /** Classical Roman architectural colonnade/arch for the showcase card. */
  romanArchImage?: string
  onStartFree?: () => void
  onBookDemo?: () => void
  onWatchDemo?: () => void
}

