// #region icons
function OrbitLogoMark({ size = 32, className }: { size?: number; className?: string }) {
  return (
    <svg
      className={"oct-svg " + (className || "")}
      width={size}
      height={size}
      viewBox="0 0 36 36"
      fill="none"
      aria-hidden="true"
    >
      <circle cx="18" cy="18" r="14" stroke="currentColor" strokeWidth="2" strokeOpacity="0.3" />
      <ellipse
        cx="18"
        cy="18"
        rx="15"
        ry="6"
        transform="rotate(-28 18 18)"
        stroke="currentColor"
        strokeWidth="2.2"
        strokeDasharray="4 2"
      />
      <circle cx="18" cy="18" r="4.5" fill="currentColor" />
      <circle cx="28" cy="12" r="2.5" fill="#38bdf8" />
    </svg>
  )
}

