      {/* =========================================================================
          SECTION 5: FROM LEAD TO REVENUE (Pipeline Accordion + Trireme Galley)
          ========================================================================= */}
      <section className="oct-section oct-pipeline-section">
        <div className="oct-container">
          <div className="oct-pipeline-grid">
            {/* Left Column: 3-Step Accordion */}
            <div className="oct-pipeline-left">
              <h2 className="oct-serif-title">
                From Lead to
                <br />
                Revenue
              </h2>

              <div className="oct-pipeline-accordion">
                {PIPELINE_STEPS.map((step, idx) => {
                  const isActive = pipelineStep === idx
                  return (
                    <div
                      key={step.num}
                      onClick={() => setPipelineStep(idx)}
                      className={
                        "oct-pipeline-step " + (isActive ? "oct-step-active" : "")
                      }
                    >
                      <div className="oct-step-header">
                        <span className="oct-step-num">{step.num}</span>
                        <h3 className="oct-step-title">{step.title}</h3>
                      </div>
                      {isActive && (
                        <div className="oct-step-body">
                          <p>{step.desc}</p>
                          <div className="oct-step-meta">
                            <span className="oct-stat-pill">{step.stat}</span>
                            <span className="oct-badge-subtle">{step.badge}</span>
                          </div>
                        </div>
                      )}
                    </div>
                  )
                })}
              </div>
            </div>

            {/* Right Column: Ancient Warship Galley with Dot-Matrix Revenue Chart */}
            <div className="oct-pipeline-right">
              <div className="oct-warship-card">
                {/* Ancient Trireme Warship Artwork */}
                <div className="oct-warship-art">
                  <img
                    src={shipImage}
                    alt="Classical Roman trireme galley warship on ocean waves"
                    className="oct-warship-img"
                  />
                  <div className="oct-warship-overlay" />
                </div>

                {/* Overlaid Dot-Matrix Revenue Chart */}
                <div className="oct-revenue-matrix-card">
                  <div className="oct-matrix-head">
                    <div>
                      <span className="oct-kicker-sm">Revenue Intelligence</span>
                      <h4 className="oct-matrix-amount">$100K</h4>
                    </div>
                    <div className="oct-matrix-filters">
                      <span className="oct-filter-chip">Filters</span>
                      <span className="oct-filter-active">Last month</span>
                    </div>
                  </div>

                  <div className="oct-matrix-breakdown">
                    <span className="oct-breakdown-date">Sep-Nov 2026</span>
                    <div className="oct-breakdown-tags">
                      <span className="oct-tag-product">● Product: $56K</span>
                      <span className="oct-tag-services">● Services: $76K</span>
                    </div>
                  </div>

                  {/* SVG Dot Matrix Chart Canvas */}
                  <div className="oct-dot-matrix-stage">
                    {/* Authentic Dot-Matrix / Block Bar Chart matching ref3 */}
                    <div className="oct-matrix-canvas">
                      <div className="oct-matrix-y-axis">
                        <span>100K</span>
                        <span>95K</span>
                        <span>75K</span>
                        <span>50K</span>
                        <span>25K</span>
                        <span>10K</span>
                      </div>
                      <div className="oct-matrix-bars-container">
                        {[
                          { month: "Apr", blocks: 6, prod: 2 },
                          { month: "May", blocks: 8, prod: 4 },
                          { month: "June", blocks: 11, prod: 6 },
                          { month: "July", blocks: 9, prod: 5 },
                          { month: "Aug", blocks: 12, prod: 7 },
                          { month: "Sep", blocks: 13, prod: 8 },
                          { month: "Oct", blocks: 14, prod: 9 },
                          { month: "Nov", blocks: 15, prod: 10 },
                        ].map((col, cIdx) => (
                          <div key={col.month} className="oct-matrix-col">
                            <div className="oct-matrix-blocks">
                              {Array.from({ length: 15 }).map((_, bIdx) => {
                                const level = 15 - bIdx
                                const isFilled = level <= col.blocks
                                const isProd = level <= col.prod
                                return (
                                  <span
                                    key={bIdx}
                                    className={
                                      "oct-matrix-block " +
                                      (isFilled
                                        ? isProd
                                        ? "oct-block-prod"
                                        : "oct-block-services"
                                        : "oct-block-empty")
                                    }
                                  />
                                )
                              })}
                            </div>
                            <span className="oct-matrix-x-label">{col.month}</span>
                          </div>
                        ))}
                      </div>

                      {/* Floating Tooltip */}
                      <div className="oct-matrix-hover-tooltip">
                        <div className="oct-tt-head">Sep - Nov 2026</div>
                        <div className="oct-tt-row">
                          <span className="oct-tt-prod">Product</span>
                          <strong>$56K</strong>
                        </div>
                        <div className="oct-tt-row">
                          <span className="oct-tt-serv">Services</span>
                          <strong>$76K</strong>
                        </div>
                        <div className="oct-tt-delta">+6 since last weeks</div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

